function maximumPoints(enemyEnergies, currentEnergy) {
  let weakest = Infinity;
  let total = 0;
  for (const energy of enemyEnergies) {
    weakest = Math.min(weakest, energy);
    total += energy;
  }
  if (currentEnergy < weakest) {
    return 0;
  }
  const pool = currentEnergy + total - weakest;
  return Math.floor(pool / weakest);
}

