function maximumPoints(enemyEnergies, currentEnergy) {
  // Tries every sequence of moves, memoised on (marked set, energy, whether a point is held).
  const n = enemyEnergies.length;
  const memo = new Map();
  const best = (mask, energy, scored) => {
    const key = (energy * 4096 + mask) * 2 + scored;
    if (memo.has(key)) return memo.get(key);
    let result = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) continue;
      if (energy >= enemyEnergies[i]) result = Math.max(result, 1 + best(mask, energy - enemyEnergies[i], 1));
      if (scored) result = Math.max(result, best(mask | (1 << i), energy + enemyEnergies[i], 1));
    }
    memo.set(key, result);
    return result;
  };
  return best(0, currentEnergy, 0);
}

