function generate(rand, size) {
  if (size === 'large') {
    const n = 1500 + Math.floor(rand() * 501);
    const high = rand() < 0.5 ? 1000000000 : 1000;
    const enemyEnergies = Array.from({ length: n }, () => 1 + Math.floor(rand() * high));
    return [enemyEnergies, Math.floor(rand() * 1000000001)];
  }
  const n = 1 + Math.floor(rand() * 5);
  const enemyEnergies = Array.from({ length: n }, () => 1 + Math.floor(rand() * 6));
  return [enemyEnergies, Math.floor(rand() * 13)];
}
